ALTER TABLE public.membership_plans ADD COLUMN access_categories text[] NOT NULL DEFAULT ARRAY['courses','classes','webinars','seminars','ebooks']::text[], ADD COLUMN access_days integer NOT NULL DEFAULT 0;
ALTER TABLE public.memberships ADD COLUMN access_categories text[] NOT NULL DEFAULT ARRAY['courses','classes','webinars','seminars','ebooks']::text[];
ALTER TABLE public.membership_plans ADD CONSTRAINT membership_plan_categories_valid CHECK (cardinality(access_categories)>0 AND access_categories <@ ARRAY['courses','classes','webinars','seminars','ebooks']::text[]), ADD CONSTRAINT membership_plan_days_valid CHECK (access_days BETWEEN 0 AND 36500);
CREATE OR REPLACE FUNCTION public.membership_category_matches(_categories text[], _category text) RETURNS boolean LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT coalesce(_category=ANY(_categories),false) $$;
CREATE OR REPLACE FUNCTION public.has_membership_category(_category text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND EXISTS(SELECT 1 FROM public.profiles WHERE id=auth.uid() AND account_status='active') AND EXISTS(SELECT 1 FROM public.memberships m WHERE m.user_id=auth.uid() AND m.starts_at<=now() AND (m.expires_at IS NULL OR m.expires_at>now()) AND public.membership_category_matches(m.access_categories,_category)) $$;
REVOKE ALL ON FUNCTION public.has_membership_category(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.has_membership_category(text) TO authenticated;
CREATE OR REPLACE FUNCTION public.snapshot_membership_access() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.membership_plans; BEGIN SELECT * INTO p FROM public.membership_plans WHERE id=NEW.plan_id; IF NOT FOUND THEN RAISE EXCEPTION 'Plan unavailable'; END IF; NEW.access_categories:=p.access_categories; SELECT greatest(now(),coalesce(max(m.expires_at),now())) INTO NEW.starts_at FROM public.memberships m WHERE m.user_id=NEW.user_id AND m.plan_id=NEW.plan_id AND m.expires_at IS NOT NULL; NEW.expires_at:=CASE WHEN p.access_days>0 THEN NEW.starts_at+make_interval(days=>p.access_days) WHEN p.billing_period='monthly' THEN NEW.starts_at+interval '1 month' WHEN p.billing_period='yearly' THEN NEW.starts_at+interval '1 year' ELSE NULL END; RETURN NEW; END $$;
CREATE TRIGGER snapshot_membership_access BEFORE INSERT ON public.memberships FOR EACH ROW EXECUTE FUNCTION public.snapshot_membership_access();
DO $$ DECLARE f record; definition text; replacement text; BEGIN FOR f IN SELECT oid,proname FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname IN ('has_course_access','member_enroll','my_ebook_resource','can_read_ebook_file','my_session_access') LOOP definition:=pg_get_functiondef(f.oid); replacement:=CASE WHEN f.proname IN ('has_course_access','member_enroll') THEN 'public.has_membership_category(''courses'')' WHEN f.proname IN ('my_ebook_resource','can_read_ebook_file') THEN 'public.has_membership_category(''ebooks'')' ELSE 'public.has_membership_category(CASE s.kind WHEN ''webinar'' THEN ''webinars'' WHEN ''seminar'' THEN ''seminars'' ELSE ''classes'' END)' END; definition:=replace(definition,'public.has_active_membership(auth.uid())',replacement); EXECUTE definition; END LOOP; END $$;
CREATE OR REPLACE FUNCTION public.my_membership() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('active',public.has_active_membership(auth.uid()),'plan_name',(SELECT m.plan_name FROM public.memberships m WHERE m.user_id=auth.uid() AND m.starts_at<=now() AND (m.expires_at IS NULL OR m.expires_at>now()) ORDER BY m.expires_at DESC NULLS FIRST LIMIT 1),'expires_at',(SELECT m.expires_at FROM public.memberships m WHERE m.user_id=auth.uid() AND m.starts_at<=now() AND (m.expires_at IS NULL OR m.expires_at>now()) ORDER BY m.expires_at DESC NULLS FIRST LIMIT 1),'access_categories',coalesce((SELECT jsonb_agg(DISTINCT c.category) FROM public.memberships m CROSS JOIN LATERAL unnest(m.access_categories) c(category) WHERE m.user_id=auth.uid() AND m.starts_at<=now() AND (m.expires_at IS NULL OR m.expires_at>now()) AND public.has_active_membership(auth.uid())),'[]'::jsonb)) $$;
COMMENT ON COLUMN public.memberships.access_categories IS 'Immutable purchase-time product category entitlement snapshot; later plan edits apply only to new purchases.';